// The uploaded files as one base64 payload: a single query parameter, free of the commas the Postgres node splits on.
const message = $input.first().json;
const files = [];
for (const file of message.files || []) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, file.binaryKey);
  files.push({ file_name: file.fileName, mime_type: file.mimeType, data: buffer.toString('base64') });
}
const payload = Buffer.from(JSON.stringify({ session_id: message.sessionId, files })).toString('base64');
return [{ json: { payload } }];
